@layer component {
  .alert {
    display: flex;
    align-items: flex-start;
    gap: 1rem;
    background-color: color-mix(in oklch, var(--c-variant) 70%, light-dark(white, black));
    padding: 1rem;
    width: 100%;
    color: color-mix(in oklch, var(--c-variant) 30%, light-dark(black, white));

    .icon {
      position: relative;
      flex-shrink: 0;
      width: 1.5rem;
      height: 1.5rem;
    }

    .content {
      display: flex;
      position: relative;
      flex-direction: column;
      gap: 0.25rem;

      .title {
        margin: 0;
        font-weight: 900;
        letter-spacing: 0.025em;
      }

      .body {
        opacity: 0.9;
        font-weight: 500;
        font-size: 0.875rem;
        line-height: 1.25rem;
      }
    }
  }
}

import { useCachedStyles } from '@/hook/useCachedStyles';
import { getCommonProps, type CommonPropsWithAs, type WithVariant } from '@/lib/utils';
import commonClasses from '@/style/common.module.css';
import type { ElementType, ReactNode } from 'react';
import classes from './alert.module.css';

const ALERT_CLASSES = `${commonClasses.base} ${commonClasses.shadow} ${classes.alert}`;
export function Alert<E extends ElementType = 'div'>({
  as,
  icon,
  title,
  style,
  role = 'alert',
  children,
  ...props
}: WithVariant<CommonPropsWithAs<E, { icon?: ReactNode; title?: ReactNode }>>) {
  const Comp = as ?? 'div';
  const cStyles = useCachedStyles();

  return (
    <Comp
      style={{ ...cStyles, ...style }}
      {...getCommonProps({ variant: 'secondary', ...props }, ALERT_CLASSES)}
      role={role}
    >
      {icon && <span className={classes.icon}>{icon}</span>}
      <div className={classes.content}>
        {title && <h5 className={classes.title}>{title}</h5>}
        <div className={classes.body}>{children}</div>
      </div>
    </Comp>
  );
}
